const toJstDate = (d) => new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Tokyo', year: 'numeric', month: '2-digit', day: '2-digit' }).format(d);

const now = new Date();
const [year, month, day] = toJstDate(now).split('-').map(Number);
const todayJstUtc = new Date(Date.UTC(year, month - 1, day));
todayJstUtc.setUTCDate(todayJstUtc.getUTCDate() - 1);
const yesterdayStr = toJstDate(todayJstUtc);

// 各RSSアイテムが由来するフィード（Build Feed List）を pairedItem から特定し tags を引き当てる
const feeds = $('Build Feed List').all();
const getFeedIdx = (pi) => {
  if (pi === null || pi === undefined) return 0;
  if (typeof pi === 'number') return pi;
  if (Array.isArray(pi)) return getFeedIdx(pi[0]);
  if (typeof pi === 'object') return pi.item != null ? pi.item : 0;
  return 0;
};

const output = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const j = item.json || {};
  const candidateDate = j.isoDate || j.pubDate || j.published || j.updated || j['dc:date'];
  if (!candidateDate) continue;

  const dateObj = new Date(candidateDate);
  if (Number.isNaN(dateObj.getTime())) continue;

  const updatedDateStr = toJstDate(dateObj);
  if (updatedDateStr !== yesterdayStr) continue;

  const author = j.creator || j.author || j['dc:creator'] || (j.meta && j.meta.title) || '';
  const body = j['content:encoded'] || j.content || j.contentSnippet || j.description || '';

  const feedIdx = getFeedIdx(item.pairedItem);
  const feed = feeds[feedIdx];
  const tags = (feed && feed.json && Array.isArray(feed.json.tags) && feed.json.tags.length) ? feed.json.tags : ['note'];

  output.push({
    json: {
      title: j.title || '',
      link: j.link || j.guid || '',
      author,
      updatedDateJst: updatedDateStr,
      body,
      tags
    },
    pairedItem: { item: i }
  });
}

return output;

// URL単位で重複を排除し、複数フィードで検出された同一記事のタグを統合する
const byLink = new Map();
const output = [];
for (const item of items) {
  const j = item.json || {};
  const link = j.link || '';
  const tags = Array.isArray(j.tags) ? j.tags : [];
  if (!link) {
    // link が無い場合は重複判定できないためそのまま通す
    output.push({ json: { ...j, tags: tags.slice() } });
    continue;
  }
  if (byLink.has(link)) {
    const exj = byLink.get(link).json;
    for (const t of tags) {
      if (!exj.tags.includes(t)) exj.tags.push(t);
    }
    // より情報量の多い本文を採用
    if ((j.body || '').length > (exj.body || '').length) exj.body = j.body;
  } else {
    const entry = { json: { ...j, tags: tags.slice() } };
    byLink.set(link, entry);
    output.push(entry);
  }
}
return output;

